<header class="page-header"><div><h1><?= e(t('Trends & workload')) ?></h1><p><?= e(t('Insights from your saved records, with dates and sample sizes.')) ?></p></div><form method="get" action="/insights/trends"><input type="month" name="month" value="<?= e($month) ?>" required><button class="secondary"><?= e(t('View')) ?></button></form></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card"><h2><?= e(t('Spending trends')) ?></h2><?php $s=$trends['spending']; if ($s): ?><p><?= e($month) ?>: <?= money($s['current']['total']) ?> <?= e(t('from')) ?> <?= e($s['current']['n']) ?> <?= e(t('entries; previous month')) ?> <?= money($s['previous']['total']) ?> <?= e(t('from')) ?> <?= e($s['previous']['n']) ?> <?= e(t('entries.')) ?></p><p><?= $s['change_percent']===null?t('A completed selected month, at least three entries in each month and a nonzero prior total are needed for a comparison.'):e($s['change_percent']).'% change in recorded monthly spending.' ?></p><p><?= e(t('Weekend:')) ?> <?= $s['weekend_daily']===null?t('Need two recorded weekend days'):money($s['weekend_daily']).' per recorded day' ?><?= e(t('. Weekdays:')) ?> <?= $s['weekday_daily']===null?t('Need three recorded weekdays'):money($s['weekday_daily']).' per recorded day' ?>.</p><p class="muted"><?= e(t('Only days with expense entries are included in daily averages. Missing entries affect these comparisons; they do not predict future spending.')) ?></p><?php else: ?><p><?= e(t('Enable Money to see spending trends.')) ?></p><?php endif; ?></section>
<section class="card"><h2><?= e(t('Habit trends')) ?></h2><?php foreach ($trends['habits'] as $h): ?><p><strong><?= e($h['title']) ?></strong>: <?= e($h['current_count']) ?> <?= e(t('check-ins across')) ?> <?= e($h['eligible_days']) ?> <?= e(t('elapsed eligible days.')) ?> <?= $h['rate']===null?t('Seven elapsed days needed for a rate.'):e($h['rate']).'%' ?><?php if ($h['comparable']): ?><br><?= e(t('Previous month:')) ?> <?= e($h['previous_count']) ?> <?= e(t('check-ins.')) ?><?php endif; ?></p><?php endforeach; ?><?php if (!$trends['habits']): ?><p><?= e(t('No active habits yet.')) ?></p><?php endif; ?></section></div>
<section class="card"><h2><?= e(t('Failure Journal patterns')) ?></h2><p class="muted"><?= e(t('Exact matching root causes, normalized for case and whitespace, in the 90 days before')) ?> <?= e($trends['period'][1]) ?><?= e(t('. These are prompts for reflection.')) ?></p><?php foreach ($trends['patterns'] as $p): ?><article><h3><?= e($p['cause']) ?></h3><p><?= e($p['count']) ?> <?= e(t('entries across')) ?> <?= e(implode(', ',$p['areas'])) ?>. <?= e($p['first'].' → '.$p['last']) ?></p><p><?= e(t('Source entry IDs:')) ?> <?= e(implode(', ',$p['ids'])) ?>. <?= e($p['suggestion']) ?></p><a href="/lessons"><?= e(t('Review journal')) ?></a></article><?php endforeach; ?><?php if (!$trends['patterns']): ?><p><?= e(t('No repeated root causes in the recorded period.')) ?></p><?php endif; ?></section>
<section class="card"><h2><?= e(t('Related patterns to review')) ?></h2><?php foreach($trends['related_patterns'] as $pattern): ?><article class="lesson-entry"><h3><?= e($pattern['label']) ?></h3><p><?= e($pattern['reason']) ?></p><p><?= e($pattern['count']) ?> <?= e(t('entries across')) ?> <?= e(implode(', ',$pattern['areas'])) ?></p><details><summary><?= e(t('Review the evidence')) ?></summary><?php foreach($pattern['evidence'] as $evidence): ?><p><strong>#<?= e($evidence['id']) ?> · <?= e($evidence['date']) ?></strong><br><?= e($evidence['text']) ?></p><?php endforeach; ?></details><p><?= e($pattern['suggestion']) ?></p><a href="/lessons"><?= e(t('Review journal')) ?></a></article><?php endforeach; ?><?php if(!$trends['related_patterns']): ?><p class="muted"><?= e(t('Not enough related entries to suggest a pattern.')) ?></p><?php endif; ?></section>
<section class="card"><h2><?= e(t('Workload reminders')) ?></h2><?php foreach ($trends['overload'] as $o): ?><p role="status"><strong><?= e($o['title']) ?></strong><br><?= e($o['body']) ?></p><?php endforeach; ?><form class="stack" action="/insights/trends/preferences" method="post"><?= csrf_field() ?><label><input type="checkbox" name="enabled" <?= Db::setting('wellbeing_enabled')==='1'?'checked':'' ?>><?= e(t('Enable workload reminders')) ?></label><label><?= e(t('Daily capacity (minutes)')) ?><input type="number" name="daily_minutes" min="30" max="1440" value="<?= e(Db::setting('wellbeing_daily_minutes','480')) ?>" required></label><label><?= e(t('Due/overdue task threshold')) ?><input type="number" name="open_tasks" min="1" max="200" value="<?= e(Db::setting('wellbeing_open_tasks','12')) ?>" required></label><p class="muted"><?= e(t('Uses estimated tasks, appointments and recorded focus. Sleep is not inferred. This is a planning reminder.')) ?></p><button><?= e(t('Save')) ?></button></form></section>
